/*
 * src: /app/root/nomeacao/static/cadastramento/Restful.js
 */
 Ext._define("nomeacao.cadastramento.Restful", {
    extend: 'core.Restful',

    resource: 'NOMConviteNomeacao',

    getFields: function() {
        if(!this._fields){
            this._fields = nomeacao.cadastramento.Restful.superclass.getFields.call(this, {}).concat([
                {type: "int", name: "comarca", useNull: true},
                {type: "string", name: "cpf"},
                {type: "string", name: "nome"},
                {type: "string", name: "nome_social"},
                {type: "bool", name: "sinc_form", useNull: true},
                {type: "datetime", name: "created_at"},
            ]);
        }
        return this._fields;
    }
});
/*
 * src: /app/root/nomeacao/static/cadastramento/Window.js
 */
Ext._define('nomeacao.cadastramento.Window', {
    extend: 'core.RestfulWindow',

    rest: 'nomeacao.cadastramento.Restful',

    width: 650,

    getFormPanel: function(cfg) {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: true,
                items: [
                    {
                        xtype: "textfield", 
                        fieldLabel: "CPF", 
                        allowBlank: true,
                        disabled: true,
                        width: 500,
                        name: "cpf",
                    },
                    {
                        xtype: "textfield", 
                        fieldLabel: "Nome", 
                        allowBlank: true,
                        disabled: true,
                        width: 500,
                        name: "nome",
                    },
                    {
                        xtype: "textfield", 
                        fieldLabel: "Nome Social",
                        allowBlank: true,
                        disabled: true,
                        width: 500,
                        name: "nome_social",
                    },
                    {
                        xtype: "textfield", 
                        fieldLabel: "Sincronizado em",
                        allowBlank: true,
                        disabled: true,
                        width: 500,
                        name: "created_at",
                    },
                    // {
                    //     allowBlank: true,
                    //     fieldLabel: 'Sincronizar?',
                    //     name: 'sinc_form',
                    //     xtype: 'checkbox'
                    // },
                ]
            });

        return this._formPanel;
    }
});

/*
 * src: /app/root/nomeacao/static/cadastramento/Grid.js
 */
 Ext._define('nomeacao.cadastramento.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'nomeacao.cadastramento.Window',

    configOrderToolBar: [
        'search',
    ],

    hideActions: ['add', 'edit', 'copy', 'remove', 'download'],

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Chave', dataIndex: 'pk', id: 'autoExpandColumn', hidden: true},
                    {header: 'CPF', dataIndex: 'cpf', width: 150},
                    {header: 'Nome', dataIndex: 'nome', width: 300},
                    {header: 'Nome Social', dataIndex: 'nome_social', width: 300},
                    // {header: 'Sincronizar?', dataIndex: 'sinc_form', width: 70, renderer: toolkit.util.formatIconYesNo},
                    {header: 'Sincronizado Em', dataIndex: 'created_at', width: 100},
                ]
            );

        return this._columnModel;
    },

    _realizarReq: function(params, nome_classe, nome_metodo){
        Ext.Ajax.request({
            url: toolkit.util.Normalize.controller_action(nome_classe,nome_metodo),
            params: params,
            success: function(request) {
                var obj = Ext.decode(request.responseText);
                var icon = obj.success == true ? Ext.Msg.INFO : Ext.Msg.ERROR;
                Ext.Msg.show({
                    width:"400px",
                    title: this.title,
                    icon: icon,
                    buttons: Ext.Msg.OK,
                    msg: obj.message
                });
                if(obj.success == true){ this.getStore().reload(); }
            },
            failure: function() {
                Ext.Msg.show({
                    title: this.title,
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK,
                    msg: 'Recurso indisponivel no momento, tente novamente mais tarde.'
                });
            },
            scope: this
        });
    },

    sincConvidado: function(data){
        var msg = 'Tem certeza que deseja sincronizar os dados para '+ data.cpf + ' - ' + data.nome +'?';

        Ext.Msg.show({
            msg: msg,
            icon: Ext.Msg.QUESTION,
            buttons: Ext.Msg.YESNO,
            scope: this,
            fn: function (b) {
                if (b == 'no') return;

                params = { 'cpf': data.cpf };
                this._realizarReq(params, 'NOMConviteNomeacao', 'sincronizar_convidado');
            }
        });
    },

    getConfigCustomActions: function(){
        return [
            {
                iconCls: 'icon-16px icon-core icon-core-run',
                tooltip: 'Sincronizar',
                scope: this,
                handler: function(action, index){ this.sincConvidado(action._store.getAt(index).data); },
            },
        ];
    },

});

core.RestfulGrid.register(
    'nomeacao.cadastramento.Restful',
    'nomeacao.cadastramento.Grid'
);
/*
 * src: /app/root/nomeacao/static/cadastramento/Manage.js
 */
Ext._define('nomeacao.cadastramento.Manage', {
	extend: 'toolkit.widget.TabPanel',

	getGrid: function(cfg) {
		if(!this._grid){
			this._grid = Ext._create('nomeacao.cadastramento.Grid', {
				region: 'center',
			});
		}

		return this._grid;
	},

    constructor: function(cfg) {
		cfg = cfg ? cfg : {};

		Ext.applyIf(
			cfg,
			{
			   title: 'Convidados à Nomeação'
			}
		);

		Ext.apply(
			cfg,
			{
				layout: 'border',
				items: this.getGrid(cfg)
			}
		);
		nomeacao.cadastramento.Manage.superclass.constructor.call(this, cfg);
	}
});
